What exactly does this JavaScript program print? Assume standard semantics of a modern browser or Node.js. Do not run it — trace it.

```js
function elevator(requests, start) {
  let floor = start, dir = -1, time = 0;
  const pending = new Set(requests);
  const served = [];
  while (pending.size > 0) {
    if (pending.has(floor)) {
      pending.delete(floor);
      served.push(floor);
      time += 3;
    }
    const ahead = [...pending].some((f) => (f - floor) * dir > 0);
    if (!ahead) dir = -dir;
    floor += dir;
    time += 1;
  }
  return served.join('>') + ' t=' + time + ' end=' + floor;
}

